struct RecursiveMutexInternalState {
    // Ownership tracking (critical for fast path reentry)
    std::thread::id owner_id;

    // Recursion count (must be volatile/atomic to avoid optimization)
    std::atomic<int> recursion_depth = 0;

    // Compiler optimization relies on the runtime check:
    bool is_owner(std::thread::id current) const {
        return owner_id == current;
    }

    // Assembly detail: recursion path bypasses kernel/OS wait.
    void recursive_lock() {
        recursion_depth.fetch_add(1, std::memory_order_relaxed);
    }
};
